// #e0da25 (6a993d6e89df7f29e9e0da25) — запись звонка и её защищённое хранение (F-36). Кейсы REC-012…REC-015.
// БЕЗ звонков: по ГОТОВЫМ попыткам 21.10 (только чтение) → @prod-safe.
//  - полная запись: QA-C4-2110-D2 (попытка 045d7b08, 315 с, конец по таймеру) — запись привязана к попытке, is_partial=false,
//    длительность записи = длительности попытки, в отчёте нет «ההקלטה חלקית»;
//  - частичная запись после сбоя: кандидат с текущей попыткой technical_failure и recording.is_partial=true —
//    запись сохранена (> 0 с) и в отчёте «ההקלטה חלקית: חלק מהשיחה לא נקלט…». QA-C6-2110-D2 (запись 69bd634e, 102 с) сброшен
//    21.10 и его отчёт теперь показывает вторую попытку — без другого такого кандидата тест падает с пометкой «нет данных»;
//  - плеер: клик по реплике 01:41 (101.67 с) → перемотка к ~102 с;
//  - get-recording-url: anon → 401, сессия business → 200.
// Звук ставится на паузу. Отчёт business — только десктоп (L-20261014-5).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '@playwright/test';
import { openWithApi, Api, SUPABASE_URL } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#e0da25 · #6a993d6e89df7f29e9e0da25';
const FULL = process.env.QA_E0DA25_FULL_CANDIDATE || 'QA-C4-2110-D2';
const PARTIAL = process.env.QA_E0DA25_PARTIAL_CANDIDATE || ''; // пусто — первый кандидат с is_partial=true
const PARTIAL_TEXT = /ההקלטה חלקית: חלק מהשיחה לא נקלט/;
const SEEK_LABEL = process.env.QA_E0DA25_SEEK_TIME || '01:41';

type Report = {
  attempt?: { id: string; status: string; attempt_type: string; duration_seconds: number } | null;
  recording?: { id: string; is_partial: boolean; duration_seconds: number } | null;
  transcript?: { segments?: { start: number; end: number }[] } | null;
};
type Row = { id: string; full_name: string; attempt: { status: string; attempt_type?: string } | null };

async function rows(api: Api): Promise<Row[]> {
  const res = await api.rpc('list_candidates');
  expect(res.status(), await res.text()).toBe(200);
  return (await res.json()) as Row[];
}

async function report(api: Api, id: string): Promise<Report> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: id, p_reason: null });
  expect(res.ok(), `get_candidate_report ${res.status()}`).toBeTruthy();
  const j = await res.json();
  return (Array.isArray(j) ? j[0] : j) as Report;
}

async function fullCandidate(page: Page) {
  const api = await openWithApi(page, '/candidates');
  const c = (await rows(api)).filter((r) => r.full_name === FULL);
  expect(c, `кандидат «${FULL}» (QA_E0DA25_FULL_CANDIDATE)`).toHaveLength(1);
  return { api, id: c[0].id, rep: await report(api, c[0].id) };
}

test.describe(`Запись звонка и защищённое хранение (${HASH})`, () => {
  test(`${FULL}: запись полной попытки привязана к ней, is_partial=false, длительность = длительности звонка, без «ההקלטה חלקית» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const { id, rep } = await fullCandidate(page);
    // Источник: AC1 «מוקלטת במלואה ומשויכת לרשומת הניסיון»; реджект 13.10 — неполная запись не должна помечаться полной.
    expect(rep.attempt?.attempt_type).toBe('official');
    expect(rep.attempt?.status).toBe('completed');
    expect(rep.recording, 'у попытки нет записи').toBeTruthy();
    expect(rep.recording!.is_partial, 'recording.is_partial').toBe(false);
    expect(rep.attempt!.duration_seconds, 'попытка 045d7b08 — 315 с').toBeGreaterThanOrEqual(300);
    expect(Math.abs(rep.recording!.duration_seconds - rep.attempt!.duration_seconds), 'длительность записи vs попытки').toBeLessThanOrEqual(2);

    await page.goto(`/candidates/${id}/report`);
    await expect(page.getByTestId('recording-player')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(PARTIAL_TEXT)).toHaveCount(0);
  });

  test(`после технического сбоя сохранена частичная запись: is_partial=true, > 0 с, в отчёте «ההקלטה חלקית: חלק מהשיחה לא נקלט…» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const failed = (await rows(api)).filter(
      (r) => r.attempt?.status === 'technical_failure' && r.attempt.attempt_type !== 'practice' && (!PARTIAL || r.full_name === PARTIAL),
    );
    let found: { id: string; name: string; rep: Report } | undefined;
    for (const r of failed) {
      const rep = await report(api, r.id);
      if (rep.recording?.is_partial) {
        found = { id: r.id, name: r.full_name, rep };
        break;
      }
    }
    expect(
      found,
      `нет данных: нет кандидата с текущей попыткой technical_failure и частичной записью (QA-C6-2110-D2 сброшен 21.10). ` +
        `Задайте QA_E0DA25_PARTIAL_CANDIDATE после ручного обрыва звонка.`,
    ).toBeTruthy();

    // Источник: AC3 / דרישה 3 — часть, записанная до обрыва, сохранена и не удалена; реджект 13.10 — помечена как частичная.
    expect(found!.rep.recording!.duration_seconds, `${found!.name}: длительность частичной записи`).toBeGreaterThan(0);
    await page.goto(`/candidates/${found!.id}/report`);
    await expect(page.getByTestId('recording-player')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(PARTIAL_TEXT)).toBeVisible();
  });

  test(`${FULL}: клик по реплике ${SEEK_LABEL} в транскрипте перематывает запись к её началу (~102 с) @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const { id } = await fullCandidate(page);
    await page.goto(`/candidates/${id}/report`);
    await expect(page.getByTestId('recording-player')).toBeVisible({ timeout: 30_000 });
    await expect
      .poll(() => page.evaluate(() => document.querySelector('audio')?.readyState ?? 0), { message: 'запись не загрузилась', timeout: 20_000 })
      .toBeGreaterThanOrEqual(1);
    await page.evaluate(() => {
      const a = document.querySelector('audio')!;
      const w = window as unknown as { __seeks: number[] };
      w.__seeks = [];
      a.addEventListener('seeked', () => w.__seeks.push(a.currentTime));
    });

    const segment = page.getByTestId('transcript-segment').filter({ has: page.getByTestId('segment-time').getByText(SEEK_LABEL, { exact: true }) });
    await expect(segment).toHaveCount(1);
    const start = Number(await segment.getAttribute('data-start'));
    await segment.scrollIntoViewIfNeeded();
    await segment.click();

    // Источник: דרישה 2 «ההקלטה זמינה להאזנה מתוך הדוח, מסונכרנת לתמלול» — 21.10: 01:41 → ~102 с.
    const lastSeek = () => page.evaluate(() => (window as unknown as { __seeks: number[] }).__seeks.at(-1) ?? -1);
    await expect.poll(async () => Math.abs((await lastSeek()) - start) <= 0.5, { message: `перемотка к ${start} с (±0.5)` }).toBe(true);
    expect(start).toBeGreaterThanOrEqual(101);
    expect(start).toBeLessThan(102);
    await page.evaluate(() => document.querySelector('audio')!.pause());
  });

  test(`${FULL}: get-recording-url без входа (anon) → 401; с сессией business → 200 @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const { api, rep } = await fullCandidate(page);
    expect(rep.recording?.id, 'у отчёта нет записи').toBeTruthy();
    const url = `${SUPABASE_URL}/functions/v1/get-recording-url`;
    const data = { recording_id: rep.recording!.id };

    // Источник: AC4 / דרישה 4 — без права на кандидата доступ к записи отклоняется.
    const anon = await page.request.post(url, {
      headers: { apikey: api.headers.apikey, authorization: `Bearer ${api.headers.apikey}`, 'content-type': 'application/json' },
      data,
    });
    expect(anon.status(), await anon.text()).toBe(401);

    const own = await page.request.post(url, { headers: api.headers, data });
    expect(own.status(), await own.text()).toBe(200);
  });
});
